function Avatar({ name, photo, idx=0, size=50, radius=12 }) {
  if (photo) {
    return (
      <img src={photo} alt={name}
        style={{ width:size, height:size, borderRadius:radius, objectFit:"cover", objectPosition:"top", flexShrink:0, display:"block" }}/>
    );
  }
  const initials = (name||"?").split(" ").map(w=>w[0]).join("").slice(0,2);
  const [bg, fg] = AV_COLORS[idx % AV_COLORS.length];
  return (
    <svg width={size} height={size} viewBox="0 0 50 50"
      style={{ borderRadius:radius, flexShrink:0, display:"block" }}>
      <rect width="50" height="50" fill={bg}/>
      <text x="25" y="33" textAnchor="middle" fill={fg}
        fontSize="19" fontWeight="800" fontFamily="'DM Sans',Arial,sans-serif">
        {initials}
      </text>
    </svg>
  );
}
function SportBg({ sport, height=140, children }) {
  const m = SPORT_META[sport] || SPORT_META.football;
  const id = `g${sport}`;
  return (
    <div style={{ position:"relative", height, width:"100%", overflow:"hidden" }}>
      <svg width="100%" height="100%" style={{ position:"absolute", inset:0 }}>
        <defs>
          <radialGradient id={id} cx="30%" cy="30%" r="80%">
            <stop offset="0%" stopColor={m.color} stopOpacity="0.35"/>
            <stop offset="100%" stopColor={m.bg} stopOpacity="1"/>
          </radialGradient>
        </defs>
        <rect width="100%" height="100%" fill={`url(#${id})`}/>
        {/* decorative circles */}
        <circle cx="80%" cy="25%" r="45" fill={m.color} fillOpacity="0.08"/>
        <circle cx="15%" cy="70%" r="30" fill={m.color} fillOpacity="0.06"/>
        <text x="78%" y="62%" fontSize="52" textAnchor="middle" dominantBaseline="middle"
          opacity="0.25">{m.icon}</text>
      </svg>
      <div style={{ position:"relative", zIndex:1, height:"100%", display:"flex", flexDirection:"column", justifyContent:"flex-end" }}>
        {children}
      </div>
    </div>
  );
}
function dist(a,b,c,d){
  const R=6371, dL=(c-a)*Math.PI/180, dG=(d-b)*Math.PI/180;
  const x=Math.sin(dL/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(dG/2)**2;
  return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));
}
