function CoachCard({ coach, userCoords, onClick }) {
  const km = userCoords ? Math.round(dist(userCoords.lat,userCoords.lng,coach.lat,coach.lng)*10)/10 : null;
  const m = SPORT_META[coach.sport];
  return (
    <div onClick={() => onClick(coach)}
      style={{
        flexShrink:0, width:148, height:210, borderRadius:16,
        overflow:"hidden", cursor:"pointer", position:"relative",
        transition:"transform 0.18s",
      }}
      onMouseEnter={e=>e.currentTarget.style.transform="scale(1.03)"}
      onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"}>

      {/* Full bleed photo */}
      {coach.photo
        ? <img src={coach.photo} alt={coach.name} style={{ position:"absolute", inset:0, width:"100%", height:"100%", objectFit:"cover", objectPosition:"top center" }}/>
        : <div style={{ position:"absolute", inset:0, background:`radial-gradient(ellipse at 30% 20%,${m.color}55,${m.bg})` }}/>
      }

      {/* Thin gradient only at very bottom */}
      <div style={{ position:"absolute", inset:0, background:"linear-gradient(to top, rgba(5,10,14,0.92) 0%, rgba(5,10,14,0.3) 35%, transparent 60%)" }}/>

      {/* Rating — top left, tiny */}
      <div style={{ position:"absolute", top:8, left:8, background:"rgba(5,10,14,0.72)", backdropFilter:"blur(8px)", borderRadius:8, padding:"3px 7px", fontSize:10, fontWeight:800, color:"#F7DC6F", display:"flex", alignItems:"center", gap:3 }}>
        {Icon.star} {coach.rating}
      </div>

      {/* Sport badge — top right, tiny */}
      <div style={{ position:"absolute", top:8, right:8, background:m.color, borderRadius:6, padding:"2px 7px", fontSize:9, fontWeight:800, color:"#031014" }}>
        {m.label}
      </div>

      {/* Text — pinned to bottom, minimal */}
      <div style={{ position:"absolute", bottom:0, left:0, right:0, padding:"8px 10px 10px" }}>
        <div style={{ fontWeight:800, fontSize:13, color:"#fff", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{coach.name}</div>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:3 }}>
          <div style={{ color:"rgba(255,255,255,0.5)", fontSize:10 }}>{km !== null ? `${km} ק״מ` : coach.loc}</div>
          <div style={{ color:C.teal, fontWeight:900, fontSize:13 }}>₪{coach.price+FEE}</div>
        </div>
      </div>
    </div>
  );
}
function Carousel({ coaches, userCoords, onSelect }) {
  const ref = useRef(null);
  const [active, setActive] = useState(0);
  const CARD_W = 148 + 12; // card width + gap

  // Sort by rating * reviews for ranking
  const ranked = [...coaches].sort((a,b) => (b.rating*b.reviews) - (a.rating*a.reviews));
  const rankMap = {};
  ranked.forEach((c,i) => rankMap[c.id] = i+1);

  return (
    <div style={{ marginBottom:16 }}>
      <style>{`
        .sc { scroll-snap-align: start; }
        .carousel-scroll {
          display: flex;
          gap: 12px;
          overflow-x: scroll;
          padding: 4px 20px 10px;
          scroll-snap-type: x mandatory;
          -webkit-overflow-scrolling: touch;
          scrollbar-width: none;
        }
        .carousel-scroll::-webkit-scrollbar { display: none; }
      `}</style>

      <div
        ref={ref}
        className="carousel-scroll"
        onScroll={() => {
          if (ref.current) {
            const idx = Math.round(ref.current.scrollLeft / CARD_W);
            setActive(Math.min(idx, coaches.length - 1));
          }
        }}
      >
        {coaches.length === 0
          ? <div style={{ color:C.muted, fontSize:14, padding:"40px 0" }}>לא נמצאו מאמנים בסביבתך</div>
          : coaches.map(c => (
              <div key={c.id} className="sc" style={{ position:"relative", flexShrink:0 }}>
                {/* Rank badge */}
                <div style={{
                  position:"absolute", top:-6, right:-6, zIndex:10,
                  width:26, height:26, borderRadius:"50%",
                  background: rankMap[c.id]===1 ? "linear-gradient(135deg,#FFD700,#FFA500)"
                            : rankMap[c.id]===2 ? "linear-gradient(135deg,#C0C0C0,#A8A8A8)"
                            : rankMap[c.id]===3 ? "linear-gradient(135deg,#CD7F32,#A0522D)"
                            : C.card2,
                  border: `2px solid ${rankMap[c.id]<=3 ? "rgba(255,255,255,0.3)" : C.border}`,
                  display:"flex", alignItems:"center", justifyContent:"center",
                  fontSize:10, fontWeight:900,
                  color: rankMap[c.id]<=3 ? "#031014" : C.muted,
                  boxShadow: rankMap[c.id]<=3 ? "0 2px 8px rgba(0,0,0,0.4)" : "none",
                }}>
                  {rankMap[c.id]}
                </div>
                <CoachCard coach={c} userCoords={userCoords} onClick={onSelect}/>
              </div>
            ))
        }
      </div>

      {/* Dots */}
      {coaches.length > 1 && (
        <div style={{ display:"flex", justifyContent:"center", gap:5 }}>
          {coaches.map((_,i) => (
            <div key={i} style={{ width:i===active?18:5, height:5, borderRadius:3, background:i===active?C.teal:C.border, transition:"all 0.25s" }}/>
          ))}
        </div>
      )}
    </div>
  );
}
