function useTimer(ms, onDone) {
  const [pct, setPct] = useState(0);
  useEffect(() => {
    const start = Date.now();
    const id = setInterval(() => {
      const p = Math.min(100, ((Date.now()-start)/ms)*100);
      setPct(p);
      if (p >= 100) { clearInterval(id); onDone && onDone(); }
    }, 40);
    return () => clearInterval(id);
  }, []);
  return pct;
}
function GradBtn({ children, onClick, disabled=false, outline=false }) {
  return (
    <button
      onClick={disabled ? undefined : onClick}
      style={{
        width:"100%",
        padding:"17px",
        borderRadius:18,
        fontSize:17,
        fontWeight:900,
        fontFamily:"inherit",
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.45 : 1,
        border: outline ? `1px solid ${C.border}` : "none",
        background: disabled ? C.card2 : outline ? "transparent" : `linear-gradient(135deg,${C.green},${C.blue})`,
        color: disabled ? C.muted : outline ? C.muted : "#031014",
        boxShadow: disabled || outline ? "none" : `0 8px 24px rgba(23,201,100,0.3)`,
        transition:"opacity 0.2s",
      }}>
      {children}
    </button>
  );
}

function Input({ placeholder, value, onChange, type="text" }) {
  const [focused, setFocused] = useState(false);
  const active = focused || value;
  return (
    <div style={{ position:"relative" }}>
      <input
        type={type} value={value} onChange={e => onChange(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        style={{
          background: focused ? `${C.green}08` : C.card,
          border:`1.5px solid ${focused ? C.green : value ? C.green+"66" : C.border}`,
          borderRadius:14, padding:"20px 18px 10px",
          color:C.text, fontSize:16, fontFamily:"inherit",
          outline:"none", width:"100%", direction:"rtl",
          transition:"all 0.2s",
          boxShadow: focused ? `0 0 0 3px ${C.green}15` : "none",
        }}
        placeholder={focused ? "" : placeholder}
      />
      {active && (
        <div style={{
          position:"absolute", top:8, right:18,
          fontSize:10, fontWeight:700, color:C.green,
          transition:"all 0.2s", letterSpacing:0.5,
        }}>{placeholder}</div>
      )}
      {value && (
        <div style={{ position:"absolute", top:"50%", left:14, transform:"translateY(-50%)", color:C.green, fontSize:14 }}>✓</div>
      )}
    </div>
  );
}
