function StepBar({ step, total=6 }) {
  return (
    <div style={{ padding:"14px 20px 0" }}>
      <div style={{ display:"flex", gap:5 }}>
        {Array.from({length:total}).map((_,i) => (
          <div key={i} style={{ flex:1, height:4, borderRadius:2, background:C.border, overflow:"hidden", position:"relative" }}>
            <div style={{
              position:"absolute", inset:0,
              background: i < step ? C.green : `linear-gradient(90deg,${C.green},${C.blue})`,
              transform: i < step ? "scaleX(1)" : i===step ? "scaleX(1)" : "scaleX(0)",
              transformOrigin:"left",
              transition:"transform 0.5s cubic-bezier(0.4,0,0.2,1)",
            }}/>
          </div>
        ))}
      </div>
      <div style={{ textAlign:"center", marginTop:6, color:C.muted, fontSize:11 }}>
        שלב {step+1} מתוך {total}
      </div>
    </div>
  );
}
