            <circle cx="50" cy="50" r="44" fill="none" stroke={step>=4?C.green:C.blue} strokeWidth="4"
              strokeDasharray={step>=4?"276 0":`${step*60} 216`} strokeLinecap="round" transform="rotate(-90 50 50)"
              style={{ transition:"all 0.5s" }}/>
