function VerStep1({ player, results, onDone }) {
  const [step, setStep] = useState(0);
  const steps = ["מתחבר ל-football.org.il","מחפש לפי שם ושנת לידה","שולף נתוני שחקן","בודק רישום תקף"];
  
  // Advance animation steps
  useEffect(() => {
    const t1 = setTimeout(()=>setStep(1), 700);
    const t2 = setTimeout(()=>setStep(2), 1500);
    const t3 = setTimeout(()=>setStep(3), 2300);
    const t4 = setTimeout(()=>setStep(4), 3100);
    return ()=>[t1,t2,t3,t4].forEach(clearTimeout);
  }, []);

  // Advance when animation done - with or without results
  useEffect(() => {
    if (step >= 4) {
      setTimeout(onDone, 800);
    }
  }, [step]);
  return (
    <div style={{ paddingTop:32, textAlign:"center" }}>
      <div style={{ fontSize:48, marginBottom:16, display:"inline-block", animation:step<4?"spin 1.2s linear infinite":"none" }}>⚽</div>
      <div style={{ fontSize:20, fontWeight:900, color:"#E8F4F8", marginBottom:4 }}>{step>=4?"נמצא! ✅":"מחפש..."}</div>
      <div style={{ color:"#5A8090", fontSize:13, marginBottom:24 }}>{player?.first} {player?.last} · {player?.year}</div>
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {steps.map((s,i)=>(
          <div key={i} style={{ background:i<step?"#17C96412":"#0D1E2A", border:`1px solid ${i<step?"#17C96444":"#143040"}`, borderRadius:12, padding:"11px 16px", display:"flex", justifyContent:"space-between", transition:"all 0.3s" }}>
            <span style={{ fontSize:13, color:i<step?"#E8F4F8":"#5A8090" }}>{s}</span>
            <span style={{ color:i<step?"#17C964":"#5A8090", fontWeight:700 }}>{i<step?"✓":i===step?"...":"—"}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

