function Screen4({ player, onNext }) {
  const [phase, setPhase] = useState(0); // 0=blink,1=turn,2=smile,3=done
  const [subPct, setSubPct] = useState(0);

  useEffect(() => {
    if (phase >= 3) return;
    setSubPct(0);
    const start = Date.now();
    const dur = 2000;
    const id = setInterval(() => {
      const p = Math.min(100,((Date.now()-start)/dur)*100);
      setSubPct(p);
      if (p >= 100) { clearInterval(id); setTimeout(() => setPhase(ph => ph+1), 300); }
    }, 40);
    return () => clearInterval(id);
  }, [phase]);

  useEffect(() => { if (phase === 3) setTimeout(onNext, 1200); }, [phase]);

  const checks = [
    { icon:"eye", label:"מצמוץ", desc:"עצום ופתח עיניים" },
    { icon:"turn", label:"סיבוב ראש", desc:"הסתכל שמאלה וימינה" },
    { icon:"smile", label:"חיוך", desc:"חייך לכמה שניות" },
  ];

  return (
    <div style={{ padding:"24px 20px" }}>
      <Badge color={C.blue}>אימות חיות</Badge>
      <div style={{ fontSize:24, fontWeight:900, margin:"14px 0 4px" }}>זיהוי פנים חי</div>
      <div style={{ color:C.muted, fontSize:14, marginBottom:22 }}>
        מוודא שאתה שחקן אמיתי ולא תמונה
      </div>

      {/* Camera frame */}
      <div style={{ position:"relative", width:"100%", paddingBottom:"75%", marginBottom:22 }}>
        <div style={{
          position:"absolute", inset:0,
          background:`radial-gradient(ellipse at center, #1A3A2A 0%, ${C.bg} 70%)`,
          borderRadius:24, border:`2px solid ${phase===3 ? C.green : C.blue}44`,
          overflow:"hidden",
          boxShadow: phase===3 ? `0 0 40px ${C.greenGlow}` : `0 0 40px ${C.blueGlow}`,
        }}>
          {/* Corner brackets */}
          {[[0,0,"0 0 0 0","15px 0 0 15px"],[0,null,null,"15px 0 0 15px"],[null,0,null,null],[null,null,null,null]].map((_,i) => {
            const pos = [{top:16,right:16},{top:16,left:16},{bottom:16,right:16},{bottom:16,left:16}][i];
            const rot = [0,90,270,180][i];
            return (
              <div key={i} style={{
                position:"absolute", ...pos, width:24, height:24,
                borderTop:`2px solid ${phase===3 ? C.green : C.blue}`,
                borderRight:`2px solid ${phase===3 ? C.green : C.blue}`,
                transform:`rotate(${rot}deg)`,
              }}/>
            );
          })}
          {/* Face placeholder */}
          <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:12 }}>
            <div style={{
              width:100, height:100, borderRadius:"50%",
              background:`radial-gradient(circle,${C.card2},${C.bg})`,
              border:`2px dashed ${phase===3 ? C.green+"88" : C.blue+"88"}`,
              display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:52, transition:"all 0.4s",
            }}>
              <span style={{color: phase===3 ? C.green : C.blue, opacity: phase===3?1:0.7}}>{phase===3 ? Icon.check : Icon.camera}</span>
            </div>
            {phase < 3 && (
              <div style={{ textAlign:"center" }}>
                <div style={{ fontWeight:800, fontSize:15, color:"#fff" }}>{checks[phase].label}</div>
                <div style={{ color:C.muted, fontSize:12, marginTop:3 }}>{checks[phase].desc}</div>
                {/* progress bar */}
                <div style={{ width:120, height:4, background:C.border, borderRadius:2, margin:"10px auto 0", overflow:"hidden" }}>
                  <div style={{ height:"100%", width:`${subPct}%`, background:`linear-gradient(90deg,${C.blue},${C.green})`, borderRadius:2, transition:"width 0.04s" }}/>
                </div>
              </div>
            )}
            {phase === 3 && <div style={{ color:C.green, fontWeight:900, fontSize:16 }}>כל הבדיקות עברו! ✓</div>}
          </div>
        </div>
      </div>

      {/* Checks list */}
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {checks.map((c,i) => (
          <div key={i} style={{
            background: i < phase ? `${C.green}12` : i === phase ? `${C.blue}10` : C.card,
            border:`1px solid ${i < phase ? C.green+"44" : i===phase ? C.blue+"44" : C.border}`,
            borderRadius:12, padding:"11px 16px",
            display:"flex", justifyContent:"space-between", alignItems:"center",
            transition:"all 0.4s",
          }}>
            <span style={{ display:"flex", alignItems:"center", gap:10, fontSize:14 }}>
              <IconEl name={c.icon} size={16} color="currentColor"/> {c.label}
            </span>
            <span style={{
              fontSize:13, fontWeight:800,
              color: i < phase ? C.green : i===phase ? C.blue : C.muted,
            }}>
              {i < phase ? "✓ עבר" : i===phase ? "בתהליך..." : "ממתין"}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
